-- pg_vectorsearch on Tiger Cloud: extension and schema setup.
--
-- The synthetic incident-memory dataset is generated by generate_data.py.
-- It models a fictional e-commerce platform and contains no real customer,
-- vendor, or employee information.
--
-- Usage:
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f setup.sql

-- 1. Extension -----------------------------------------------------------

CREATE EXTENSION IF NOT EXISTS pg_vectorsearch;

-- 2. Table ---------------------------------------------------------------

CREATE TABLE IF NOT EXISTS incident_events (
  id              bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  occurred_at     timestamptz NOT NULL,
  service         text NOT NULL,
  severity        text NOT NULL,
  incident_id     text,
  incident_family text,
  content         text NOT NULL,
  metadata        jsonb NOT NULL DEFAULT '{}'::jsonb,
  -- PLAIN keeps the full vector inline for PRISM's exact reranking step.
  embedding       vec32(1536) STORAGE PLAIN,
  content_tsv     tsvector GENERATED ALWAYS AS
                  (to_tsvector('english'::regconfig, content)) STORED
);

-- CREATE TABLE IF NOT EXISTS does not update an existing column's storage.
ALTER TABLE incident_events ALTER COLUMN embedding SET STORAGE PLAIN;

-- 3. Sample data ---------------------------------------------------------
-- load.py creates and loads the deterministic sample after this script runs.

-- 4. Indexes -------------------------------------------------------------
-- Run indexes.sql after embed.py. PRISM sizes and trains the index from the
-- vectors present at CREATE INDEX time.
